(()=>{'use strict';const root=document.getElementById('root');let alive=true,seq=0,requests=new Map(),state={accounts:{},active:''},user=null,accountChecked=false,loaded=false,readFailed=false,busy=false,syncing=false,edit=null,message='',error='',trash=false,voice='',timer;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const uid=()=>crypto.randomUUID?crypto.randomUUID():'a'+Date.now().toString(36)+Math.random().toString(36).slice(2);function rpc(action,data={}){return new Promise((resolve,reject)=>{const id='today-'+(++seq),t=setTimeout(()=>{requests.delete(id);reject(Error('连接暂时不可用'))},15000);requests.set(id,{resolve,reject,t});parent.postMessage({type:'atom:market',id,action,data},'*')})}window.addEventListener('message',e=>{if(e.source!==parent)return;const d=e.data;if(d?.type==='atom:market-result'){const p=requests.get(d.id);if(!p)return;requests.delete(d.id);clearTimeout(p.t);if(d.error){const er=Error(d.error);er.status=d.status;er.current=d.current;p.reject(er)}else p.resolve(d.result)}if(d?.type==='atom:agenda-voice'){voice=d.state==='recording'?'正在聆听…':d.state==='transcribing'?'正在转写…':d.error||'';if(d.state==='done'&&d.text){if(!edit)edit={id:uid(),revision:0,title:'',kind:'todo',starts_at:'',done:false,deleted:false};edit.title=(edit.title+' '+d.text).trim().slice(0,200)}render()}});const bucket=()=>state.accounts[state.active];async function commit(fn){if(readFailed)throw Error('请先重试读取记录');const old=JSON.stringify(state);try{fn();if(new TextEncoder().encode(JSON.stringify(state)).length>55000)throw Error('本机缓存已满，请先同步待办');await AtomApp.save(state)}catch(e){state=JSON.parse(old);throw e}}function render(){if(!alive)return;const b=bucket(),conf=b?.pending.find(x=>x.conflict);root.innerHTML='<header><button data-atom-back data-action="back" aria-label="返回上一级">‹ '+(edit||trash?'今日':'桌面')+'</button><div class="today-heading"><div class="day">'+new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})+'</div><h1>今日</h1></div><button data-action="'+(edit?'cancel':'new')+'">'+(edit?'取消':'＋ 添加')+'</button></header>'+(readFailed?'<div class="notice">读取本机数据失败，不会覆盖原记录。<button data-action="retry-load">重试</button></div>':!accountChecked?'<div class="empty" role="status"><h2>'+(error?'暂时无法连接':'正在同步日程…')+'</h2><p>'+(error?esc(error):'正在确认账号并读取事项')+'</p>'+(error?'<button data-action="refresh">重试</button>':'')+'</div>':!user?'<div class="empty"><h2>让今天井井有条</h2><p>登录 ATOM 账号后，<br>和电脑上的日程、待办同步。</p><button data-action="go-login" class="primary">去登录</button><button data-action="refresh" class="secondary">已登录，刷新</button></div>':conf?'<div class="notice">这条记录在电脑上也被修改了，本机内容已保留。</div><div class="list"><div class="item"><div class="text"><p>本机版本</p><strong>'+esc(conf.title)+'</strong></div></div><div class="item"><div class="text"><p>云端版本</p><strong>'+esc(conf.conflict.title)+'</strong></div></div></div><div class="actions"><button data-action="copy">保留两份</button><button data-action="remote">采用云端</button></div>':edit?'<div class="editor"><input id="title" aria-label="事项标题" maxlength="200" placeholder="想安排什么？" value="'+esc(edit.title)+'"><div class="two"><select id="kind" aria-label="事项类型"><option value="todo" '+(edit.kind==='todo'?'selected':'')+'>待办</option><option value="event" '+(edit.kind==='event'?'selected':'')+'>日程</option></select><input id="when" aria-label="时间" type="datetime-local" value="'+esc(edit.starts_at?new Date(new Date(edit.starts_at).getTime()-new Date().getTimezoneOffset()*60000).toISOString().slice(0,16):'')+'"></div><p>按住空格说出安排，松手后确认保存。</p><div style="flex:1"></div><button data-action="save" class="primary" '+(busy?'disabled':'')+'>保存到今日</button></div>':'<div class="list">'+(b?.items||[]).filter(x=>x.deleted===trash).sort((a,b)=>Number(a.done)-Number(b.done)||String(a.starts_at).localeCompare(String(b.starts_at))).map(x=>'<div class="item '+(x.done?'done':'')+'"><button class="check" data-toggle="'+x.id+'" aria-label="切换完成状态">'+(x.done?'✓':'')+'</button><div class="text"><strong>'+esc(x.title)+'</strong><p>'+esc(x.kind==='event'?'日程':'待办')+(x.starts_at?' · '+esc(new Date(x.starts_at).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})):'')+'</p></div><button class="small" data-edit="'+x.id+'">编辑</button><button class="small '+(!trash?'danger':'')+'" data-delete="'+x.id+'">'+(trash?'恢复':'移除')+'</button></div>').join('')+(!(b?.items||[]).some(x=>x.deleted===trash)?'<div class="empty"><h2>'+(trash?'暂无已移除事项':'给今天留一点空间')+'</h2><p>安排一件值得完成的小事。</p></div>':'')+'</div>')+'<div class="feedback">'+esc(error||voice||message)+'</div>'+(user&&!edit&&!conf?'<footer><p>'+esc(user.username)+' · '+((b?.pending.length||0)?b.pending.length+' 条待同步':'已同步')+'</p><div><button class="small" data-action="trash">'+(trash?'返回今日':'已移除')+'</button><button class="small" data-action="sync">同步</button></div></footer>':'');if(!loaded||busy)root.querySelectorAll('button').forEach(x=>x.disabled=true);if(window.AtomApp&&!render.ready){AtomApp.ready();render.ready=true}}
async function enqueue(item){const b=bucket();await commit(()=>{const previous=b.pending.find(x=>x.id===item.id);const clean={...item,op_id:uid(),revision:previous?.revision??item.revision??0};delete clean.conflict;b.pending=b.pending.filter(x=>x.id!==item.id);b.pending.push(clean);b.items=b.items.filter(x=>x.id!==item.id);b.items.unshift({...clean});if(b.pending.length>24||b.items.length>60)throw Error('本机事项过多，请先同步并整理')});message='已保存在本机，等待同步';error='';void sync()}
