.screen,body>main{height:100%;max-height:100vh;overflow:hidden;padding:18px 22px;gap:10px;min-height:0}
.header,body>main>header{height:40px;min-height:40px;flex-shrink:0;gap:12px}
h1{font-size:27px;line-height:1.18;letter-spacing:-1px;font-weight:700;margin:0}h2{font-size:18px;letter-spacing:-.45px}h3{font-size:15px;letter-spacing:-.2px}
.header button,body>main>header>button{min-height:32px;border-radius:18px;padding:6px 12px;font-size:12px}
button{min-height:36px;border-radius:11px;font-weight:550;padding:8px 12px}button.secondary{background:var(--atom-card,#fff);color:var(--atom-accent,#007aff)}
input,select,textarea{border:0!important;background:var(--atom-card,#fff);border-radius:12px;min-width:0;color:inherit}input,select{min-height:36px;padding:8px 11px}
.scroll,.list,section#list{min-height:0;overscroll-behavior:contain;overflow-x:hidden}
.card{border-radius:16px;padding:14px;margin-bottom:10px;box-shadow:none}.card h2{margin-bottom:7px}.muted,small{color:var(--atom-secondary-text,#74777f);font-size:11px;line-height:1.55}
.notice{padding:8px 11px;line-height:1.45;font-size:11px;border-radius:10px;flex-shrink:0}.notice.error{background:#fff0ed;color:#a63931}
.segments,.mode-selector{padding:3px;gap:3px;border-radius:11px;background:var(--atom-line,#e8e9ee);flex-shrink:0}.segments button,.mode-selector button{min-height:28px;font-size:12px;padding:4px 8px;border-radius:8px}.segments button[aria-pressed=true],.mode-selector button[aria-pressed=true]{box-shadow:0 1px 4px #20212412;font-weight:650}
.field{margin:8px 0}.field>span{font-size:11px;letter-spacing:.1px;margin-bottom:4px}.empty{min-height:0}.empty h2{font-size:21px;letter-spacing:-.6px}.empty p{font-size:12px;line-height:1.7}.actions{gap:7px}.pre{font-size:11px;line-height:1.6}
/* Notes: a quiet notebook, not a stack of dashboard widgets. */
body[data-atom-app=quick-notes] .screen{gap:9px}
