body[data-atom-app=quick-notes] .note-open{font-size:17px;font-weight:650;line-height:1.45;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
body[data-atom-app=quick-notes] .note-editor{background:var(--atom-card,#fff);border-radius:16px;font-size:17px;line-height:1.8;padding:17px 18px;box-shadow:inset 3px 0 0 #eac56a}
body[data-atom-app=quick-notes] .note-body{line-height:1.75}body[data-atom-app=quick-notes] .row>.actions button{min-height:30px;background:transparent;padding:4px 8px}
